/// The `state:` of a rule (`linter/lib/src/analyzer.dart`, `State`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EstadoDaRegra {
    Estavel,
    Experimental,
    /// Only for the SDK itself.
    Interna,
    Depreciada,
    Removida,
}

/// The `package:lints` set that enables the rule.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Conjunto {
    Nenhum,
    /// `package:lints/core.yaml` (and therefore also `recommended`).
    Core,
    /// Only `package:lints/recommended.yaml`.
    Recommended,
}

/// A registered rule.
#[derive(Debug, PartialEq, Eq)]
pub struct InfoRegra {
    pub nome: &'static str,
    pub estado: EstadoDaRegra,
    /// The version of the state's `since:`, when there is one.
    pub desde: Option<(u32, u32, u32)>,
    /// `incompatibleRules`.
    pub incompativeis: &'static [&'static str],
    pub conjunto: Conjunto,
    /// The rule's file in `linter/lib/src/`.
    pub arquivo: &'static str,
}

/// A lint code (`LinterLintCode`).
#[derive(Debug, PartialEq, Eq)]
pub struct CodigoLint {
    /// The reported name (the rule's).
    pub nome: &'static str,
    /// `uniqueName`.
    pub unico: &'static str,
    pub mensagem: &'static str,
    pub correcao: Option<&'static str>,
    pub documentado: bool,
}

/// Runs every implemented rule that is enabled (`enabled(name)`) over a unit;
/// the reports come out in position order.
pub fn run(
    u: crate::Unidade<'_>,
    interner: &dartforge_intern::Interner,
    enabled: &dyn Fn(&str) -> bool,
) -> Vec<rules::LintReport> {
    run_with(u, interner, enabled, None)
}

/// The semantics of a unit whose tree is the resolved program's: what the
/// rules that the original decides by element or by type (and not by name)
/// read. Without it, those rules do not report.
#[derive(Clone, Copy)]
pub struct Semantics<'a> {
    pub program: &'a dartforge_elements::model::Program,
    pub unit: dartforge_elements::model::UnitId,
    pub body: &'a dartforge_types::resolved::UnitBodyTypes,
    /// The bodies of every unit (the rules that look at the whole library).
    pub bodies: &'a dartforge_types::resolved::BodyTypes,
    pub table: &'a dartforge_types::table::TypeTable,
    pub core: &'a dartforge_types::table::CoreTypes,
    pub outline: &'a dartforge_types::resolve::OutlineTypes,
    /// The `canBeConst` of the unit's creations, literals and constructors
    /// (`dartforge_types::typed_lints6`), when computed.
    pub can_be_const: Option<&'a dartforge_types::typed_lints6::CanBeConst>,
}

/// `FunctionBody.isPotentiallyMutatedInScope` of the local declared at
/// `decl` (the name's offset): the `ScopeResolverVisitor`'s set is one per
/// unit, so any write to the element in the unit counts — the left side of an
/// assignment (with any operator), the operand of `++`/`--`, the variable of
/// `for (x in …)` and the variable of an assignment pattern.
pub fn is_mutated(sem: &Semantics<'_>, a: &dartforge_frontend::ast::Ast, decl: usize) -> bool {
    use dartforge_frontend::ast::{CollectionElement, ExprKind, ForInTarget, StmtKind, UnaryOp};
    let is_it = |x: dartforge_frontend::ast::ExprId| sem.body.local_declaration(x) == Some(decl);
    for e in a.exprs.iter() {
        match &e.kind {
            ExprKind::Assign { target, .. } if is_it(*target) => return true,
            ExprKind::Unary { op: UnaryOp::PrefixInc | UnaryOp::PrefixDec | UnaryOp::PostfixInc | UnaryOp::PostfixDec, operand } if is_it(*operand) => {
                return true;
            }
            ExprKind::List { elements, .. } | ExprKind::SetOrMap { elements, .. } => {
                fn in_collection(el: &CollectionElement, is_it: &dyn Fn(dartforge_frontend::ast::ExprId) -> bool) -> bool {
                    match el {
                        CollectionElement::ForIn { target, body, .. } => {
                            matches!(target, ForInTarget::Expression(x) if is_it(*x)) || in_collection(body, is_it)
                        }
                        CollectionElement::For { body, .. } => in_collection(body, is_it),
                        CollectionElement::If { then, else_, .. } => in_collection(then, is_it) || else_.as_ref().is_some_and(|x| in_collection(x, is_it)),
                        _ => false,
                    }
                }
                if elements.iter().any(|el| in_collection(el, &is_it)) {
                    return true;
                }
            }
            _ => {}
        }
    }
    if a.stmts.iter().any(|s| matches!(&s.kind, StmtKind::ForIn { target: ForInTarget::Expression(x), .. } if is_it(*x))) {
        return true;
    }
    sem.body.pattern_declarations.values().any(|d| *d == decl)
}

/// The `canonicalElement` of a resolved element: a local by its declaration;
/// an accessor (implicit, or the explicit getter/setter pair) by the variable
/// or by the synthetic property the analyzer creates for it; the rest by the
/// element itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Canonical {
    Local(usize),
    Parameter(dartforge_intern::SymbolId),
    Variable(dartforge_elements::model::VariableId),
    /// The explicit `get x`/`set x` pair: the owner (class, extension or
    /// library) and the name without `=`.
    Property(PropertyOwner, dartforge_intern::SymbolId),
    Function(dartforge_elements::model::FunctionElementId),
    Element(dartforge_elements::model::Element),
    TypeParameter(dartforge_types::table::TypeParamId),
    Prefix(dartforge_elements::model::LibraryId),
}

/// The owner of a synthetic property.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PropertyOwner {
    Class(dartforge_elements::model::ClassId),
    Extension(dartforge_elements::model::ExtensionId),
    Library(dartforge_elements::model::LibraryId),
}

/// The canonical element of function `f` (an accessor counts as its variable/property).
fn function_canonical(sem: &Semantics<'_>, interner: &dartforge_intern::Interner, f: dartforge_elements::model::FunctionElementId) -> Canonical {
    use dartforge_elements::model::FunctionKind;
    let g = sem.program.function(f);
    if let Some(v) = g.variable {
        return Canonical::Variable(v);
    }
    if matches!(g.kind, FunctionKind::Getter | FunctionKind::Setter) {
        let text = interner.resolve(g.name);
        let base = text.strip_suffix("_=").or_else(|| text.strip_suffix('=')).unwrap_or(text);
        let name = interner.lookup(base).unwrap_or(g.name);
        let owner = match (g.class, g.extension) {
            (Some(c), _) => PropertyOwner::Class(c),
            (None, Some(x)) => PropertyOwner::Extension(x),
            (None, None) => PropertyOwner::Library(g.library),
        };
        return Canonical::Property(owner, name);
    }
    Canonical::Function(f)
}

/// `node.staticElement?.canonicalElement` (or the write element, on the left
/// side of an assignment: `getWriteOrReadElement`) of expression `e`.
pub fn canonical(sem: &Semantics<'_>, interner: &dartforge_intern::Interner, e: dartforge_frontend::ast::ExprId) -> Option<Canonical> {
    use dartforge_elements::model::Element;
    use dartforge_types::resolved::{MemberRef, Resolved};
    Some(match sem.body.get_resolved(e)? {
        Resolved::Local(_) => Canonical::Local(sem.body.local_declaration(e)?),
        Resolved::Parameter { name, .. } => Canonical::Parameter(*name),
        Resolved::TypeParameter(p) => Canonical::TypeParameter(*p),
        Resolved::Element(Element::Variable(v)) | Resolved::Member { member: MemberRef::Variable(v), .. } => Canonical::Variable(*v),
        Resolved::Element(Element::Function(f))
        | Resolved::Member { member: MemberRef::Function(f), .. }
        | Resolved::ExtensionMember { member: f, .. }
        | Resolved::Constructor(f) => function_canonical(sem, interner, *f),
        Resolved::Element(x) => Canonical::Element(*x),
        Resolved::Prefix(lib) => Canonical::Prefix(*lib),
        Resolved::Dynamic => return None,
    })
}

/// `canonicalElementsFromIdentifiersAreEqual`: both are simple identifiers,
/// prefixed identifiers or property accesses (without the parentheses) with
/// the same canonical elements (and the same prefixes/targets). Two unknown
/// elements are equal (`null == null`).
pub fn same_elements(
    sem: &Semantics<'_>,
    interner: &dartforge_intern::Interner,
    a: &dartforge_frontend::ast::Ast,
    x: Option<dartforge_frontend::ast::ExprId>,
    y: Option<dartforge_frontend::ast::ExprId>,
) -> bool {
    use dartforge_frontend::ast::ExprKind;
    let (Some(x), Some(y)) = (x, y) else { return false };
    let without_parens = |mut e: dartforge_frontend::ast::ExprId| {
        while let ExprKind::Parenthesized(i) = &a.expr(e).kind {
            e = *i;
        }
        e
    };
    let (x, y) = (without_parens(x), without_parens(y));
    // The `PrefixedIdentifier`: `p.x` with `p` a simple identifier, without `?.`.
    let prefixed = |e: dartforge_frontend::ast::ExprId| match &a.expr(e).kind {
        ExprKind::Property { target, null_aware: false, .. } => matches!(a.expr(*target).kind, ExprKind::Identifier(_)).then_some(*target),
        _ => None,
    };
    match (&a.expr(x).kind, &a.expr(y).kind) {
        (ExprKind::Identifier(_), ExprKind::Identifier(_)) => canonical(sem, interner, x) == canonical(sem, interner, y),
        (ExprKind::Identifier(_), _) | (_, ExprKind::Identifier(_)) => false,
        (ExprKind::Property { target: t1, .. }, ExprKind::Property { target: t2, .. }) => match (prefixed(x), prefixed(y)) {
            (Some(p1), Some(p2)) => canonical(sem, interner, p1) == canonical(sem, interner, p2) && canonical(sem, interner, x) == canonical(sem, interner, y),
            (Some(_), None) | (None, Some(_)) => false,
            // `PropertyAccess`: the targets by the same rule, and the property.
            (None, None) => same_elements(sem, interner, a, Some(*t1), Some(*t2)) && canonical(sem, interner, x) == canonical(sem, interner, y),
        },
        _ => false,
    }
}

/// `TypeSystem.isNullable`: `dynamic`, `void`, `Null`, the invalid or unknown
/// type, a type with `?`, the `FutureOr` of a nullable type and a type
/// parameter promoted to nullable.
pub fn is_nullable(sem: &Semantics<'_>, t: dartforge_types::table::TypeId) -> bool {
    use dartforge_types::table::Type;
    if sem.core.is_unknown(sem.table, t) {
        return true;
    }
    match sem.table.get(t) {
        Type::Dynamic | Type::Void | Type::Null => true,
        Type::Intersection { bound, .. } => is_nullable(sem, *bound),
        Type::FutureOr { arg, nullable } => *nullable || is_nullable(sem, *arg),
        other => other.is_declared_nullable(),
    }
}

/// The element type of the top-level variable or field `v`: the written one,
/// or the inferred one (which body inference completes).
pub fn variable_type(sem: &Semantics<'_>, v: dartforge_elements::model::VariableId) -> Option<dartforge_types::table::TypeId> {
    let d = sem.outline.variables.get(v.0 as usize)?;
    d.declared_type.or(d.inferred)
}

/// The element of function `f` of the unit's tree (top-level, method,
/// accessor).
pub fn function_element(sem: &Semantics<'_>, f: dartforge_frontend::ast::FunctionId) -> Option<dartforge_elements::model::FunctionElementId> {
    let i = sem.program.functions.iter().position(|e| {
        matches!(e.node, dartforge_elements::model::FunctionRef::Function { unit, function } if unit == sem.unit && function == f)
    })?;
    Some(dartforge_elements::model::FunctionElementId(i as u32))
}

/// The implementation chain of `c` (`_implementationsOfGetter`): the class, the
/// mixins from the last to the first, and so on along the superclass chain.
/// With `inherited_setter`, there is a concrete, instance, accessible setter
/// `name=` in a class of the chain other than `c`
/// (`lookUpInheritedConcreteSetter`); without, there is an accessible getter
/// `name` in some class of the chain (`lookUpGetter`, also static or abstract).
pub fn lookup_in_chain(
    sem: &Semantics<'_>,
    interner: &dartforge_intern::Interner,
    c: dartforge_elements::model::ClassId,
    name: dartforge_intern::SymbolId,
    inherited_setter: bool,
) -> bool {
    use dartforge_elements::model::FunctionKind;
    let p = sem.program;
    let library = p.class(c).library;
    let private = interner.resolve(name).starts_with('_');
    let setter_name = interner.lookup(&format!("{}_=", interner.resolve(name)));
    let mut chain: Vec<dartforge_elements::model::ClassId> = Vec::new();
    let mut seen = std::collections::HashSet::new();
    let mut current = Some(c);
    while let Some(k) = current {
        if !seen.insert(k) {
            break;
        }
        chain.push(k);
        chain.extend(p.class(k).mixin_classes.iter().rev().copied());
        current = p.class(k).supertype_class;
    }
    chain.into_iter().any(|k| {
        let e = p.class(k);
        if private && e.library != library {
            return false;
        }
        if inherited_setter {
            k != c && setter_name.and_then(|x| e.instance_members.get(&x)).is_some_and(|f| !p.function(*f).abstract_ && !p.function(*f).static_)
        } else {
            e.instance_members.get(&name).or_else(|| e.static_members.get(&name)).is_some_and(|f| {
                matches!(p.function(*f).kind, FunctionKind::Getter | FunctionKind::ImplicitAccessor)
            })
        }
    })
}

/// The class (class, enum or extension type) that declares member `m` of the
/// unit.
pub fn member_class(sem: &Semantics<'_>, m: dartforge_frontend::ast::MemberId) -> Option<dartforge_elements::model::ClassId> {
    use dartforge_frontend::ast::DeclKind;
    let p = sem.program;
    let a = &p.unit(sem.unit).ast;
    let (di, _) = a.decls.iter().enumerate().find(|(_, d)| match &d.kind {
        DeclKind::Class(x) => x.members.contains(&m),
        DeclKind::Enum(x) => x.members.contains(&m),
        DeclKind::ExtensionType(x) => x.members.contains(&m),
        DeclKind::Mixin(x) => x.members.contains(&m),
        _ => false,
    })?;
    let i = p.classes.iter().position(|c| c.decl.is_some_and(|r| r.unit == sem.unit && r.decl.0 as usize == di))?;
    Some(dartforge_elements::model::ClassId(i as u32))
}

/// `FieldFormalParameterElement.field`: the field named `name` declared in the
/// class of constructor `m`.
pub fn class_field(sem: &Semantics<'_>, m: dartforge_frontend::ast::MemberId, name: dartforge_intern::SymbolId) -> Option<dartforge_elements::model::VariableId> {
    let c = member_class(sem, m)?;
    sem.program.class(c).fields.iter().copied().find(|v| sem.program.variable(*v).name == name)
}

/// The `superConstructorParameter` of the `super.x` parameter with index `i` of
/// constructor `m` of the unit: the called superclass constructor (through the
/// initializers' `super(…)`/`super.name(…)`, or the unnamed one) and its
/// parameter (a positional one by order among the positional `super.`s, a
/// named one by name).
pub fn super_parameter(
    sem: &Semantics<'_>,
    interner: &dartforge_intern::Interner,
    m: dartforge_frontend::ast::MemberId,
    i: usize,
) -> Option<(dartforge_elements::model::FunctionElementId, usize)> {
    use dartforge_frontend::ast::{Initializer, MemberKind, ParameterKind};
    let p = sem.program;
    let a = &p.unit(sem.unit).ast;
    let MemberKind::Constructor(k) = &a.member(m).kind else { return None };
    let sup = p.class(member_class(sem, m)?).supertype_class?;
    let name = k
        .initializers
        .iter()
        .find_map(|x| match x {
            Initializer::Super { constructor, .. } => Some(constructor.map(|n| n.sym)),
            _ => None,
        })
        .unwrap_or(None)
        .or_else(|| interner.lookup(""))?;
    let ctor = *p.class(sup).constructors.get(&name)?;
    let data = sem.outline.functions.get(ctor.0 as usize)?;
    let target = k.parameters.get(i)?;
    if !target.super_ {
        return None;
    }
    match target.kind {
        ParameterKind::Named => {
            let n = target.name?.sym;
            let j = data.parameters.iter().position(|x| x.kind == ParameterKind::Named && x.external_name.or(x.name) == Some(n))?;
            Some((ctor, j))
        }
        _ => {
            let order = k.parameters[..i].iter().filter(|x| x.super_ && x.kind != ParameterKind::Named).count();
            let j = data
                .parameters
                .iter()
                .enumerate()
                .filter(|(_, x)| x.kind != ParameterKind::Named)
                .nth(order)
                .map(|(j, _)| j)?;
            Some((ctor, j))
        }
    }
}

/// `TypeAnnotation.type` of annotation `t` of the unit: the outline's
/// (signatures) or the bodies'.
pub fn written_type(sem: &Semantics<'_>, t: dartforge_frontend::ast::TypeId) -> Option<dartforge_types::table::TypeId> {
    sem.outline.written_types.get(&(sem.unit, t)).copied().or_else(|| sem.body.annotation_types.get(&t).copied())
}

/// The return type of the element of function `f` of the unit
/// (`ExecutableElement.returnType`): the inferred one of a literal or local
/// function, or the outline's (written, or inherited from the override).
pub fn function_return(sem: &Semantics<'_>, f: dartforge_frontend::ast::FunctionId) -> Option<dartforge_types::table::TypeId> {
    if let Some(t) = sem.body.function_runtime_type(f)
        && let dartforge_types::table::Type::Function { ret, .. } = sem.table.get(t)
    {
        return Some(*ret);
    }
    let i = sem.program.functions.iter().position(|e| {
        matches!(e.node, dartforge_elements::model::FunctionRef::Function { unit, function } if unit == sem.unit && function == f)
    })?;
    sem.outline.functions.get(i).map(|d| d.return_type)
}

/// The unit's library has language version `major.minor` or later.
pub fn version_at_least(sem: &Semantics<'_>, major: u16, minor: u16) -> bool {
    let p = sem.program;
    p.library(p.unit(sem.unit).library).features.version() >= dartforge_frontend::features::LanguageVersion::new(major, minor)
}

/// `LinterContext.isInTestDirectory`: the unit defining the unit's library is
/// in the `test/` of its pub package (the folder of the nearest `pubspec.yaml`
/// above the file; without one, there is no package).
pub fn in_package_test(sem: &Semantics<'_>) -> bool {
    let p = sem.program;
    let lib = p.library(p.unit(sem.unit).library);
    let Some(path) = lib.units.first().and_then(|d| p.unit(*d).path.as_ref()) else { return false };
    let Some(root) = path.ancestors().skip(1).find(|d| d.join("pubspec.yaml").is_file()) else { return false };
    path.starts_with(root.join("test"))
}

/// Like [`run`], with the unit's semantics (`u` must be the tree of `sem`'s
/// program, with its `interner`).
pub fn run_with(
    u: crate::Unidade<'_>,
    interner: &dartforge_intern::Interner,
    enabled: &dyn Fn(&str) -> bool,
    sem: Option<&Semantics<'_>>,
) -> Vec<rules::LintReport> {
    let mut out = rules::run(u, interner, enabled, sem);
    out.extend(rules2::run(u, interner, enabled, sem));
    out.extend(rules3::run(u, interner, enabled, sem));
    out.extend(rules4::run(u, interner, enabled, sem));
    out.extend(rules5::run(u, interner, enabled, sem));
    out.extend(rules6::run(u, interner, enabled, sem));
    out.extend(rules7::run(u, interner, enabled, sem));
    out.extend(rules8::run(u, interner, enabled, sem));
    out.extend(rules9::run(u, interner, enabled, sem));
    out.extend(rules10::run(u, interner, enabled, sem));
    out.extend(rules11::run(u, interner, enabled, sem));
    out.extend(rules12::run(u, interner, enabled, sem));
    out.extend(rules13::run(u, interner, enabled, sem));
    out.extend(rules14::run(u, interner, enabled, sem));
    out.extend(rules15::run(u, interner, enabled, sem));
    out.extend(rules16::run(u, interner, enabled, sem));
    out.extend(rules17::run(u, interner, enabled, sem));
    out.extend(rules18::run(u, interner, enabled, sem));
    out.extend(rules19::run(u, interner, enabled, sem));
    out.extend(rules20::run(u, interner, enabled, sem));
    out.extend(rules21::run(u, interner, enabled, sem));
    out.extend(rules22::run(u, interner, enabled, sem));
    out.extend(rules23::run(u, interner, enabled, sem));
    out.extend(rules24::run(u, interner, enabled, sem));
    out.extend(rules25::run(u, interner, enabled, sem));
    out.extend(rules26::run(u, interner, enabled, sem));
    out.extend(rules27::run(u, interner, enabled, sem));
    out.extend(rules28::run(u, interner, enabled, sem));
    out.extend(rules29::run(u, interner, enabled, sem));
    out.extend(rules30::run(u, interner, enabled, sem));
    out.extend(rules31::run(u, interner, enabled, sem));
    out.extend(rules32::run(u, interner, enabled, sem));
    out.extend(rules33::run(u, interner, enabled, sem));
    out.sort_by_key(|r| (r.span.start, r.span.end));
    out
}

/// The registered rule named `name`.
pub fn rule(name: &str) -> Option<&'static InfoRegra> {
    tabela_g::REGRAS.iter().find(|r| r.nome == name)
}
